using System.Security.Claims;
using Microsoft.EntityFrameworkCore;
namespace TheBarcode.Api;
public static class AccountingEndpoints
{
 public static void MapAccountingApi(this WebApplication app)
 {
  var api=app.MapGroup("/api/accounting").RequireAuthorization().RequireModule("accounting");
  api.MapGet("/accounts",async(AppDbContext db,ClaimsPrincipal p)=>await db.LedgerAccounts.AsNoTracking().Where(x=>x.IsDemo==Security.IsDemo(p)&&x.Active).OrderBy(x=>x.Code).ToListAsync());
  api.MapGet("/periods",async(AppDbContext db,ClaimsPrincipal p)=>await db.AccountingPeriods.AsNoTracking().Where(x=>x.IsDemo==Security.IsDemo(p)).OrderByDescending(x=>x.Start).ToListAsync());
  api.MapGet("/overview",async(DateOnly? from,DateOnly? to,AppDbContext db,ClaimsPrincipal p)=>{
   var demo=Security.IsDemo(p);await AccountingJournalBuilder.Ensure(db,demo);var f=from??DateOnly.FromDateTime(DateTime.Today.AddDays(-29));var t=to??DateOnly.FromDateTime(DateTime.Today);if(t<f)(f,t)=(t,f);
   var salesThroughEnd=(await db.Sales.AsNoTracking().Include(x=>x.Items).Include(x=>x.Payments).AsSplitQuery().Where(x=>x.IsDemo==demo&&x.Status!="Held"&&x.Status!="PendingApproval"&&x.Status!="Cancelled"&&x.Status!="Refunded").ToListAsync()).Where(x=>DateOnly.FromDateTime(x.OccurredAt.LocalDateTime)<=t).ToList();
   var sales=salesThroughEnd.Where(x=>DateOnly.FromDateTime(x.OccurredAt.LocalDateTime)>=f).ToList();
   var expensesThroughEnd=await db.Expenses.AsNoTracking().Include(x=>x.Payments).Where(x=>x.IsDemo==demo&&x.Active&&x.Status=="Approved"&&x.Date<=t).ToListAsync();var expenses=expensesThroughEnd.Where(x=>x.Date>=f).ToList();var operatingExpenses=expenses.Where(x=>!x.Type.Equals("InventoryPurchase",StringComparison.OrdinalIgnoreCase)).ToList();var revenue=sales.Sum(x=>x.Total);var cost=sales.SelectMany(x=>x.Items).Sum(x=>x.UnitCost*x.Quantity);var expenseTotal=operatingExpenses.Sum(x=>x.Amount);var inventoryPurchases=expenses.Where(x=>x.Type.Equals("InventoryPurchase",StringComparison.OrdinalIgnoreCase)).Sum(x=>x.Amount);var collected=sales.SelectMany(x=>x.Payments).Where(x=>x.Amount>0).Sum(x=>x.Amount);var periodEnd=t.AddDays(1).ToDateTime(TimeOnly.MinValue,DateTimeKind.Utc);var receivableRows=salesThroughEnd.Select(x=>new{Due=DateOnly.FromDateTime((x.DueAt??x.OccurredAt).LocalDateTime),Balance=Math.Max(0,x.Total-x.Payments.Where(p=>p.Amount>0&&p.PaidAt.UtcDateTime<periodEnd).Sum(p=>p.Amount))}).Where(x=>x.Balance>0).ToList();var payableRows=expensesThroughEnd.Select(x=>new{Due=x.DueDate??x.Date,x.Amount,Paid=x.Payments.Count>0?x.Payments.Where(p=>p.Amount>0&&p.PaidAt.UtcDateTime<periodEnd).Sum(p=>p.Amount):x.PaidAmount}).Select(x=>new{x.Due,Balance=Math.Max(0,x.Amount-x.Paid)}).Where(x=>x.Balance>0).ToList();var receivables=receivableRows.Sum(x=>x.Balance);var payables=payableRows.Sum(x=>x.Balance);var receivablesAging=Age(receivableRows.Select(x=>(x.Due,x.Balance)),t);var payablesAging=Age(payableRows.Select(x=>(x.Due,x.Balance)),t);return Results.Ok(new{from=f,to=t,revenue,cost,grossProfit=revenue-cost,expenses=expenseTotal,inventoryPurchases,netProfit=revenue-cost-expenseTotal,collected,receivables,payables,receivablesAging,payablesAging,salesCount=sales.Count});
  }).RequireAuthorization(x=>x.RequirePermission("accounting"));
  api.MapGet("/trial-balance",async(DateOnly? from,DateOnly? to,AppDbContext db,ClaimsPrincipal p)=>{var demo=Security.IsDemo(p);await AccountingJournalBuilder.Ensure(db,demo);return await AccountingQueries.TrialBalance(db,demo,to);}).RequireAuthorization(x=>x.RequirePermission("accounting"));
  api.MapGet("/journals",async(DateOnly? from,DateOnly? to,int? take,AppDbContext db,ClaimsPrincipal p)=>{var demo=Security.IsDemo(p);await AccountingJournalBuilder.Ensure(db,demo);var q=db.JournalEntries.AsNoTracking().Include(x=>x.Lines).Where(x=>x.IsDemo==demo);if(from is not null)q=q.Where(x=>x.Date>=from);if(to is not null)q=q.Where(x=>x.Date<=to);var entries=await q.OrderByDescending(x=>x.Date).Take(Math.Clamp(take??250,1,1000)).ToListAsync();return Results.Ok(entries.OrderByDescending(x=>x.Date).ThenByDescending(x=>x.CreatedAt));}).RequireAuthorization(x=>x.RequirePermission("accounting"));
  api.MapPost("/adjustments",async(AdjustmentJournalRequest r,AppDbContext db,ClaimsPrincipal p)=>{if(r.Lines.Count<2||r.Lines.Any(x=>x.Debit<0||x.Credit<0)||Math.Round(r.Lines.Sum(x=>x.Debit)-r.Lines.Sum(x=>x.Credit),2)!=0)return Results.BadRequest(new{error="A journal must have at least two non-negative lines and balanced debits and credits"});var demo=Security.IsDemo(p);var ids=r.Lines.Select(x=>x.AccountId).Distinct().ToList();if(await db.LedgerAccounts.CountAsync(x=>ids.Contains(x.Id)&&x.IsDemo==demo&&x.Active)!=ids.Count)return Results.BadRequest(new{error="Every journal account must be active in this account"});if(await db.AccountingPeriods.AnyAsync(x=>x.IsDemo==demo&&x.Locked&&r.Date>=x.Start&&r.Date<=x.End))return Results.Conflict(new{error="The selected accounting period is locked"});var entry=new JournalEntry{Date=r.Date,SourceType="Adjustment",Memo=r.Memo.Trim(),IsDemo=demo};foreach(var l in r.Lines)entry.Lines.Add(new JournalLine{AccountId=l.AccountId,Description=l.Description?.Trim()??r.Memo.Trim(),Debit=Math.Round(l.Debit,2),Credit=Math.Round(l.Credit,2)});db.JournalEntries.Add(entry);db.AuditEvents.Add(new AuditEvent{StaffId=StaffId(p),Actor=p.Identity?.Name??"Staff",Action="Created",EntityType="JournalEntry",EntityId=entry.Id.ToString(),Details=$"Adjustment: {entry.Memo}"});await db.SaveChangesAsync();return Results.Created($"/api/accounting/journals/{entry.Id}",entry);}).RequireAuthorization(x=>x.RequireRole("Owner","Manager"));
  api.MapPost("/periods",async(AccountingPeriodRequest r,AppDbContext db,ClaimsPrincipal p)=>{if(r.End<r.Start||string.IsNullOrWhiteSpace(r.Name))return Results.BadRequest(new{error="Period name and valid dates are required"});var demo=Security.IsDemo(p);if(await db.AccountingPeriods.AnyAsync(x=>x.IsDemo==demo&&!((r.End<x.Start)||(r.Start>x.End))))return Results.Conflict(new{error="The period overlaps an existing period"});var period=new AccountingPeriod{Name=r.Name.Trim(),Start=r.Start,End=r.End,IsDemo=demo};db.AccountingPeriods.Add(period);await db.SaveChangesAsync();return Results.Created($"/api/accounting/periods/{period.Id}",period);}).RequireAuthorization(x=>x.RequireRole("Owner","Manager"));
  api.MapPut("/periods/{id:guid}/lock",async(Guid id,AppDbContext db,ClaimsPrincipal p)=>{var x=await db.AccountingPeriods.SingleOrDefaultAsync(x=>x.Id==id&&x.IsDemo==Security.IsDemo(p));if(x is null)return Results.NotFound();x.Locked=true;x.UpdatedAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync();return Results.Ok(x);}).RequireAuthorization(x=>x.RequireRole("Owner"));
 }
 static object Age(IEnumerable<(DateOnly Due,decimal Balance)> rows,DateOnly asOf){var buckets=new decimal[4];foreach(var row in rows){var days=asOf.DayNumber-row.Due.DayNumber;var index=days<=0?0:days<=30?1:days<=60?2:3;buckets[index]+=row.Balance;}return new{current=buckets[0],overdue1To30=buckets[1],overdue31To60=buckets[2],overdueOver60=buckets[3]};}
 static Guid StaffId(ClaimsPrincipal p)=>Guid.TryParse(p.FindFirst(ClaimTypes.NameIdentifier)?.Value,out var id)?id:throw new InvalidOperationException("Staff identity missing");
}
